// ── MAIN TRACKER ──────────────────────────────────────────────────────────────
function Tracker() {
  const [activeTab,    setActiveTab]    = useState(null);
  const [feedData,     setFeedData]     = useState({});
  const [loading,      setLoading]      = useState({});
  const [timestamps,   setTimestamps]   = useState({});
  const [globalRisk,   setGlobalRisk]   = useState("LOW");
  const [stockData,    setStockData]    = useState({});
  const [stockLoading, setStockLoading] = useState(false);
  const [stockUpdated, setStockUpdated] = useState(null);
  const [apiKey,       setApiKey]       = useState(localStorage.getItem("td_key")||"");
  const [ticker,       setTicker]       = useState([
    "YOUR HIGHNESS — STRATEGIC INTELLIGENCE DASHBOARD ACTIVE",
    "MONITORING: TRUMP · AMBANI · ADANI · GEOPOLITICAL · MARKETS",
    "APPLE · TESLA · META · BTC · GOLD · OIL · USD/INR · EUR/USD",
  ]);

  const activeCat   = CATEGORIES.find(c=>c.id===activeTab);
  const currentData = activeTab ? feedData[activeTab] : null;

  const loadStocks = useCallback(async () => {
    if (!apiKey) return;
    setStockLoading(true);
    const newData = { ...stockData };
    for (let i=0; i<STOCKS.length; i++) {
      const s = STOCKS[i];
      try {
        const res = await fetch(TD_QUOTE(s.symbol, apiKey));
        if (!res.ok) continue;
        const q = await res.json();
        if (q.status==="error"||(!q.close&&!q.price)) continue;
        newData[s.symbol] = { price:q.close||q.price, change:q.change, changePct:q.percent_change };
      } catch { continue; }
      if (i<STOCKS.length-1) await new Promise(r=>setTimeout(r,500));
    }
    setStockData(newData);
    setStockUpdated(new Date().toLocaleTimeString());
    setStockLoading(false);
  }, [apiKey]);

  useEffect(() => {
    if (apiKey) { loadStocks(); const t=setInterval(loadStocks,300000); return()=>clearInterval(t); }
  }, [apiKey, loadStocks]);

  useEffect(() => {
    if (!activeTab) return;
    const cat = CATEGORIES.find(c=>c.id===activeTab);
    const t = setInterval(()=>cat&&loadFeed(cat),600000);
    return()=>clearInterval(t);
  }, [activeTab]);

  async function loadFeed(cat) {
    if (loading[cat.id]) return;
    setLoading(p=>({...p,[cat.id]:true}));
    setActiveTab(cat.id);
    try {
      const results=[];
      for (const feedUrl of cat.feeds) {
        try {
          const res=await fetch(RSS(feedUrl));
          if (!res.ok) continue;
          const data=await res.json();
          if (data.status!=="ok"||!data.items?.length) continue;
          results.push(...data.items);
        } catch { continue; }
      }
      if (!results.length) throw new Error("NO SIGNAL — CANNOT REACH NEWS FEEDS");
      const seen=new Set();
      const articles=results
        .filter(a=>{ if(!a.title||seen.has(a.title)) return false; seen.add(a.title); return true; })
        .sort((a,b)=>new Date(b.pubDate||0)-new Date(a.pubDate||0))
        .slice(0,10);
      const risk=getRisk(articles);
      setFeedData(p=>({...p,[cat.id]:{articles,risk}}));
      setTimestamps(p=>({...p,[cat.id]:new Date().toLocaleTimeString()}));
      setGlobalRisk(p=>{ const o=["CRITICAL","HIGH","MODERATE","LOW"]; return o[Math.min(o.indexOf(p),o.indexOf(risk))]; });
      setTicker(p=>[`${cat.icon} ${cat.label} — ${articles.length} LIVE ARTICLES — RISK: ${risk}`,...p.slice(0,5)]);
    } catch(err) { setFeedData(p=>({...p,[cat.id]:{error:true,msg:err.message}})); }
    setLoading(p=>({...p,[cat.id]:false}));
  }

  return (
    <div style={{ minHeight:"100vh", background:"#030805", color:"#e8ffe8", fontFamily:"'Courier New',monospace", display:"flex", flexDirection:"column", overflow:"hidden", animation:"dashReveal .6s ease both" }}>
      <style>{`
        @keyframes ticker  { 0%{transform:translateX(0)} 100%{transform:translateX(-50%)} }
        @keyframes spin    { to{transform:rotate(360deg)} }
        @keyframes pulse   { 0%,100%{opacity:1} 50%{opacity:.2} }
        @keyframes fadein  { from{opacity:0;transform:translateY(4px)} to{opacity:1;transform:translateY(0)} }
        @keyframes blink   { 0%,100%{opacity:1} 50%{opacity:0} }
        @keyframes dashReveal { from{opacity:0} to{opacity:1} }
        .cbtn:hover { background:rgba(0,255,136,.08)!important; border-color:#00ff88!important; }
        .acard { transition:transform .12s, border-left-color .12s; }
        .acard:hover { transform:translateX(4px); border-left-color:#00ff88!important; }
        a { text-decoration:none; color:inherit; }
        ::-webkit-scrollbar { width:4px; }
        ::-webkit-scrollbar-thumb { background:#00ff8833; }
        ::-webkit-scrollbar-track { background:#000; }
      `}</style>

      {/* HEADER */}
      <div style={{ borderBottom:"2px solid #00ff88", background:"#000", flexShrink:0, position:"relative", overflow:"hidden" }}>
        <div style={{ position:"absolute", inset:0, backgroundImage:"repeating-linear-gradient(0deg,transparent,transparent 2px,rgba(0,255,136,.03) 2px,rgba(0,255,136,.03) 4px)", pointerEvents:"none" }} />
        <div style={{ padding:"10px 20px", display:"flex", alignItems:"center", gap:16, position:"relative", zIndex:1 }}>
          {/* Coat of arms in header */}
          <img src={COA} alt="CoA" style={{ height:48, width:"auto", filter:"drop-shadow(0 0 8px rgba(0,255,136,.4))", flexShrink:0 }} />
          <div style={{ flex:1 }}>
            <div style={{ fontSize:"8px", letterSpacing:"4px", color:"#00ff88", marginBottom:2, opacity:.7 }}>
              ▸ HOUSE OF OMMI &amp; BEAUMONT · STRATEGIC INTELLIGENCE UNIT · CLASSIFIED
            </div>
            <div style={{ fontSize:"18px", fontWeight:"bold", letterSpacing:"5px", color:"#ffffff", textShadow:"0 0 20px #00ff8866" }}>
              GLOBAL POWER TRACKER
            </div>
          </div>
          <div style={{ textAlign:"right" }}>
            <div style={{ fontSize:"9px", color:"#446644", letterSpacing:"3px", marginBottom:4 }}>COMPOSITE RISK</div>
            <div style={{ fontSize:"18px", fontWeight:"bold", letterSpacing:"4px", color:RISK_COLOR[globalRisk], textShadow:`0 0 16px ${RISK_COLOR[globalRisk]}` }}>
              ■ {globalRisk}
            </div>
            <div style={{ fontSize:"9px", color:"#446644", marginTop:2 }}>
              <span style={{ animation:"blink 1s infinite", color:"#00ff88" }}>●</span> ONLINE
            </div>
          </div>
        </div>
      </div>

      {/* NEWS TICKER */}
      <div style={{ background:"#001a0a", borderBottom:"1px solid #00ff8833", padding:"6px 0", overflow:"hidden", flexShrink:0 }}>
        <div style={{ display:"flex", gap:"80px", animation:"ticker 35s linear infinite", whiteSpace:"nowrap", width:"max-content" }}>
          {[...ticker,...ticker].map((t,i) => (
            <span key={i} style={{ fontSize:"10px", color:"#00ff88", letterSpacing:"2px", fontWeight:"bold" }}>◆ {t}</span>
          ))}
        </div>
      </div>

      {/* STOCK TICKER */}
      <StockBar stockData={stockData} />

      {/* BODY */}
      <div style={{ display:"flex", flex:1, overflow:"hidden" }}>

        {/* SIDEBAR */}
        <div style={{ width:220, flexShrink:0, borderRight:"2px solid #00ff8833", padding:"16px 10px", display:"flex", flexDirection:"column", gap:4, background:"#000", overflowY:"auto" }}>
          <div style={{ fontSize:9, color:"#00ff88", letterSpacing:"4px", fontWeight:"bold", padding:"0 6px", marginBottom:10, borderBottom:"1px solid #00ff8822", paddingBottom:8 }}>── INTEL FEEDS</div>
          {CATEGORIES.map(cat => {
            const isActive = activeTab===cat.id;
            const d = feedData[cat.id];
            return (
              <button key={cat.id} className="cbtn" onClick={()=>loadFeed(cat)} style={{ background:isActive?"#001a0a":"transparent", border:`1px solid ${isActive?cat.color:"#00ff8818"}`, borderLeft:`3px solid ${isActive?cat.color:"#00ff8818"}`, padding:"12px 12px", cursor:"pointer", textAlign:"left", fontFamily:"inherit", display:"flex", alignItems:"center", gap:10, transition:"all .15s", color:"#e8ffe8", width:"100%" }}>
                <span style={{ fontSize:14 }}>{cat.icon}</span>
                <div style={{ flex:1, minWidth:0 }}>
                  <div style={{ fontSize:10, fontWeight:"bold", marginBottom:3, color:isActive?"#ffffff":cat.color, letterSpacing:"1px" }}>{cat.label}</div>
                  {loading[cat.id] && <div style={{ fontSize:8, color:"#00ff88", animation:"pulse 1s infinite", letterSpacing:"2px" }}>SCANNING...</div>}
                  {!loading[cat.id] && d && !d.error && <div style={{ fontSize:8, color:RISK_COLOR[d.risk], letterSpacing:"1px", fontWeight:"bold" }}>■ {d.risk} · {timestamps[cat.id]}</div>}
                  {!loading[cat.id] && d?.error && <div style={{ fontSize:8, color:"#ff4444", letterSpacing:"1px" }}>⚠ SIGNAL LOST</div>}
                </div>
              </button>
            );
          })}
          <div style={{ marginTop:"auto", padding:"12px 8px", background:"#001a0a", border:"1px solid #00ff8833" }}>
            <div style={{ fontSize:8, color:"#446644", letterSpacing:"3px", marginBottom:6 }}>FEEDS ACTIVE</div>
            <div style={{ fontSize:24, fontWeight:"bold", color:"#00ff88", textShadow:"0 0 10px #00ff8866" }}>
              {Object.values(feedData).filter(d=>d&&!d.error).length}
              <span style={{ fontSize:12, color:"#446644", fontWeight:"normal" }}> / {CATEGORIES.length}</span>
            </div>
          </div>
        </div>

        {/* MAIN PANEL */}
        <div style={{ flex:1, overflowY:"auto", padding:24, position:"relative" }}>
          <div style={{ position:"fixed", inset:0, backgroundImage:"repeating-linear-gradient(0deg,transparent,transparent 3px,rgba(0,255,136,.008) 3px,rgba(0,255,136,.008) 4px)", pointerEvents:"none", zIndex:0 }} />

          {!activeTab && (
            <div style={{ display:"flex", flexDirection:"column", alignItems:"center", justifyContent:"center", height:"100%", gap:28, animation:"fadein .5s ease", position:"relative", zIndex:1 }}>
              <div style={{ textAlign:"center" }}>
                <div style={{ marginBottom:12, filter:"drop-shadow(0 0 20px #00ff88)" }}>
                  <img src={COA} alt="CoA" style={{ height:80, width:"auto" }} />
                </div>
                <div style={{ fontSize:16, color:"#ffffff", letterSpacing:"6px", fontWeight:"bold", marginBottom:6 }}>SELECT INTELLIGENCE FEED</div>
                <div style={{ fontSize:10, color:"#446644", letterSpacing:"3px" }}>LIVE NEWS · LIVE PRICES · AUTO-REFRESH 5–10 MIN</div>
              </div>
              <div style={{ display:"flex", gap:10, flexWrap:"wrap", justifyContent:"center" }}>
                {CATEGORIES.map(cat => (
                  <button key={cat.id} onClick={()=>loadFeed(cat)}
                    style={{ background:"#000", border:`2px solid ${cat.color}`, padding:"12px 20px", color:cat.color, cursor:"pointer", fontFamily:"inherit", fontSize:11, letterSpacing:"2px", fontWeight:"bold", transition:"all .15s" }}
                    onMouseEnter={e=>{ e.currentTarget.style.background=cat.color; e.currentTarget.style.color="#000"; }}
                    onMouseLeave={e=>{ e.currentTarget.style.background="#000"; e.currentTarget.style.color=cat.color; }}>
                    {cat.icon} {cat.label}
                  </button>
                ))}
              </div>
            </div>
          )}

          {activeTab && loading[activeTab] && (
            <div style={{ display:"flex", flexDirection:"column", alignItems:"center", justifyContent:"center", height:"60%", gap:20, position:"relative", zIndex:1 }}>
              <div style={{ width:40, height:40, border:`2px solid ${activeCat?.color}`, borderTopColor:"transparent", borderRadius:"50%", animation:"spin .7s linear infinite" }} />
              <div style={{ fontSize:11, color:"#00ff88", letterSpacing:"5px", fontWeight:"bold", animation:"pulse 1.5s infinite" }}>ACQUIRING SIGNAL...</div>
            </div>
          )}

          {activeTab && !loading[activeTab] && currentData?.error && (
            <div style={{ display:"flex", flexDirection:"column", alignItems:"center", justifyContent:"center", height:"60%", gap:16, position:"relative", zIndex:1 }}>
              <div style={{ fontSize:11, color:"#ff4444", letterSpacing:"5px", fontWeight:"bold" }}>⚠ SIGNAL LOST</div>
              <div style={{ fontSize:11, color:"#664444", maxWidth:460, textAlign:"center", padding:"14px 18px", background:"#0a0000", border:"1px solid #ff444433", lineHeight:1.8 }}>{currentData.msg}</div>
              <button onClick={()=>activeCat&&loadFeed(activeCat)} style={{ background:"transparent", border:"2px solid #ff4444", color:"#ff4444", padding:"10px 24px", cursor:"pointer", fontFamily:"inherit", fontSize:11, letterSpacing:"3px", fontWeight:"bold" }}>↺ REACQUIRE</button>
            </div>
          )}

          {activeTab && !loading[activeTab] && currentData && !currentData.error && (
            <div style={{ animation:"fadein .3s ease", position:"relative", zIndex:1 }}>
              <div style={{ display:"flex", gap:20, marginBottom:24, alignItems:"flex-start" }}>
                <div style={{ flex:1 }}>
                  <div style={{ fontSize:9, color:"#446644", letterSpacing:"4px", marginBottom:8 }}>
                    {activeCat?.icon} {activeCat?.label} · LIVE FEED · {currentData.articles?.length} ARTICLES · {timestamps[activeTab]}
                  </div>
                  <div style={{ fontSize:13, lineHeight:1.7, color:"#aaccaa", borderLeft:`3px solid ${activeCat?.color}`, paddingLeft:16 }}>
                    Live intelligence from BBC and NYT. Risk index calculated from real-time headline analysis.
                  </div>
                </div>
                <div style={{ display:"flex", flexDirection:"column", gap:8, alignItems:"flex-end", flexShrink:0 }}>
                  <div style={{ padding:"12px 20px", background:RISK_BG[currentData.risk], border:`2px solid ${RISK_COLOR[currentData.risk]}`, textAlign:"center", minWidth:100 }}>
                    <div style={{ fontSize:8, color:"#446644", letterSpacing:"3px", marginBottom:4 }}>RISK</div>
                    <div style={{ fontSize:15, fontWeight:"bold", color:RISK_COLOR[currentData.risk], letterSpacing:"3px", textShadow:`0 0 10px ${RISK_COLOR[currentData.risk]}` }}>{currentData.risk}</div>
                  </div>
                  <button onClick={()=>activeCat&&loadFeed(activeCat)} style={{ background:"transparent", border:`1px solid ${activeCat?.color}66`, color:activeCat?.color, padding:"7px 16px", cursor:"pointer", fontFamily:"inherit", fontSize:10, letterSpacing:"2px", fontWeight:"bold" }}>↺ REFRESH</button>
                </div>
              </div>
              <div style={{ display:"flex", flexDirection:"column", gap:6 }}>
                {(currentData.articles||[]).map((a,i) => {
                  const sig = getSignal(a.title,a.description);
                  return (
                    <a key={i} href={a.link} target="_blank" rel="noreferrer">
                      <div className="acard" style={{ background:"#000", border:"1px solid #00ff8818", borderLeft:"3px solid #00ff8833", padding:"14px 18px", animation:`fadein .3s ease ${i*.05}s both` }}>
                        <div style={{ display:"flex", flexWrap:"wrap", gap:10, marginBottom:8, alignItems:"center" }}>
                          <span style={{ fontSize:10, fontWeight:"bold", color:sig.color, letterSpacing:"2px" }}>{sig.icon} {sig.label}</span>
                          <span style={{ fontSize:9, color:"#334433", letterSpacing:"1px", marginLeft:"auto" }}>{timeAgo(a.pubDate)}</span>
                        </div>
                        <div style={{ fontSize:13, fontWeight:"bold", color:"#ffffff", marginBottom:6, lineHeight:1.5 }}>{a.title}</div>
                        <div style={{ fontSize:11, color:"#667766", lineHeight:1.7 }}>
                          {(a.description||"").replace(/<[^>]*>/g,"").slice(0,220)}
                          {(a.description||"").length>220?"…":""}
                        </div>
                        <div style={{ fontSize:9, color:`${activeCat?.color}99`, marginTop:8, letterSpacing:"2px", fontWeight:"bold" }}>READ FULL REPORT →</div>
                      </div>
                    </a>
                  );
                })}
              </div>
            </div>
          )}
        </div>

        <StockPanel stockData={stockData} lastUpdated={stockUpdated} onRefresh={loadStocks} loading={stockLoading} apiKey={apiKey} setApiKey={setApiKey} />
      </div>
    </div>
  );
}

// ── ROOT APP — controls login gate ────────────────────────────────────────────
export default function App() {
  const [authenticated, setAuthenticated] = useState(
    sessionStorage.getItem("auth_ommi") === "true"
  );

  function handleLogin() {
    sessionStorage.setItem("auth_ommi", "true");
    setAuthenticated(true);
  }

  if (!authenticated) return <LoginScreen onSuccess={handleLogin} />;
  return <Tracker />;
}
